$:set -euo pipefail
node <<'NODE'
"use strict";
const fs=require("node:fs"),cp=require("node:child_process"),crypto=require("node:crypto");
const dir="workspaces/codespace-mcp-srs-design/local-terminals/templates/";
const file=dir+"agent-return-wrapper.json";
for(const p of ["AGENTS.md","terminals_requirements.json","workspaces/codespace-mcp-srs-design/README.md","workspaces/codespace-mcp-srs-design/AGENTS.md",dir+"agent-command-return.schema.json",dir+"agent-command-templates.json",file])if(!fs.existsSync(p))throw Error("Required file missing: "+p);
const oldText=fs.readFileSync(file,"utf8");
const doc=JSON.parse(oldText);
const source=JSON.parse(fs.readFileSync(dir+"agent-command-return.schema.json","utf8"));
if(doc.version!=="1.2.0"||doc.derivations.length!==34||doc.compatibility.source_schema_id!==source.$id)throw Error("Unexpected wrapper baseline");
if(!source.$defs.timing.properties.elapsed_ms||!source.$defs.summary.properties.exit_code||!source.$defs.terminal.properties.terminal_id)throw Error("Expected source fields missing");
const remove=new Set(["DER-001","DER-036","DER-037"]);
for(const id of remove)if(!doc.derivations.some(x=>x.id===id))throw Error("Expected duplicate derivation missing "+id);
doc.derivations=doc.derivations.filter(x=>!remove.has(x.id));
for(const id of ["DER-024","DER-028"]){
 const d=doc.derivations.find(x=>x.id===id);
 if(!d)throw Error("Integrity derivation missing "+id);
 const allow=id==="DER-024"?["stream_id","verified"]:["stream_id","sequence","verified"];
 d.output_per_stream=undefined;
 d.output_per_chunk=undefined;
 if(id==="DER-024")d.output_per_stream=allow;
 else d.output_per_chunk=allow;
 d.deterministic_population.script_algorithm+=" Return only the boolean comparison result and the source stream/chunk correlation identifiers. Do not copy source byte_length or sha256 into the wrapper.";
 d.duplicate_source_values_excluded=["actual_byte_length","computed_sha256"];
}
doc.version="1.3.0";
doc.envelope={
 wrapper_schema:"terminals.local-terminals.agent-return-wrapper.v1",
 source_schema:"urn:terminals:local-terminals:agent-command-return:v1",
 source_execution_id:"<source.execution_id>",
 source_sha256:"<RFC8785_sha256_of_source>",
 derived:"<new_deterministically_computed_fields_only>"
};
doc.constraints.preserve_source="Do not embed, echo, or copy the source return into the wrapper. Keep the original output separately; source_execution_id and source_sha256 link the wrapper to that specific output.";
doc.constraints.non_duplication="A wrapper output field must be a new deterministic calculation or validation result absent from the source return. The sole exception is a source identifier necessary for correlating input and output, such as execution_id, run_id, run_attempt, job_id, process_record_id, stream_id, or record ID. Do not copy source values merely for convenience.";
doc.constraints.source_fidelity="Original source is immutable and referenced by source_execution_id and canonical source_sha256; no source data is repeated in the wrapper except necessary correlation keys.";
doc.verification.required_checks=doc.verification.required_checks.filter(x=>!x.includes("34 retained derivations"));
doc.verification.required_checks.push("All 31 retained derivations use deterministic scripts and do not duplicate recorded output fields except correlation identifiers.");
doc.verification.required_checks.push("Wrapper envelope references the source output by source_execution_id and source_sha256; it does not embed a second copy of the source.");
doc.verification.required_checks.push("Integrity outputs include only verified and the minimum source identifiers; original byte_length and sha256 are never repeated.");
doc.change_log=[...(doc.change_log||[]),{version:"1.3.0",removed:[...remove],reason:"Remove duplicate output-schema values while retaining correlation identifiers and new deterministic calculations.",wrapper_envelope:"reference_original_output_without_embedding",integrity_outputs:"identifiers_plus_verification_result_only"}];
const ids=doc.derivations.map(x=>x.id);
if(ids.length!==31||new Set(ids).size!==31||ids.some(x=>remove.has(x)))throw Error("Unexpected revised derivations");
if("source" in doc.envelope||!doc.envelope.source_execution_id||!doc.envelope.source_sha256)throw Error("Envelope still duplicates source");
if(JSON.stringify(doc).includes('"computed_sha256"')||JSON.stringify(doc).includes('"actual_byte_length"')){
 const a=doc.derivations.find(x=>x.id==="DER-024"),b=doc.derivations.find(x=>x.id==="DER-028");
 if(a.output_per_stream?.some(x=>["computed_sha256","actual_byte_length"].includes(x))||b.output_per_chunk?.some(x=>["computed_sha256","actual_byte_length"].includes(x)))throw Error("Duplicate integrity output values");
}
const content=JSON.stringify(doc,null,2)+"\n";
const get=p=>JSON.parse(cp.execFileSync("gh",["api","repos/BestNameYet/Terminals/contents/"+p],{encoding:"utf8"}));
const remote=get(file);
if(Buffer.from(remote.content.replace(/\s/g,""),"base64").toString("utf8")!==oldText)throw Error("Remote file changed before update");
const payload={message:"docs(local-terminals): exclude duplicate source values from return wrapper",branch:"main",sha:remote.sha,content:Buffer.from(content,"utf8").toString("base64")};
const saved=JSON.parse(cp.execFileSync("gh",["api","-X","PUT","repos/BestNameYet/Terminals/contents/"+file,"--input","-"],{encoding:"utf8",input:JSON.stringify(payload)}));
const readback=Buffer.from(get(file).content.replace(/\s/g,""),"base64").toString("utf8");
if(readback!==content)throw Error("Remote byte readback mismatch");
console.log(JSON.stringify({path:file,version:doc.version,derivations:ids.length,removed:[...remove],source_embedded:false,integrity_outputs:["stream_id/sequence","verified"],commit:saved.commit.sha,sha256:crypto.createHash("sha256").update(readback).digest("hex"),verified:true}));
NODE
